coding_problems.schema_sql:
CREATE TABLE direct_rights (actor VARCHAR(20) NOT NULL, object_name VARCHAR(20) NOT NULL, privilege_name VARCHAR(20) NOT NULL, PRIMARY KEY(actor,object_name,privilege_name));
CREATE TABLE memberships (actor VARCHAR(20) NOT NULL, role_name VARCHAR(20) NOT NULL, active INT NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(actor,role_name));
CREATE TABLE role_rights (role_name VARCHAR(20) NOT NULL, object_name VARCHAR(20) NOT NULL, privilege_name VARCHAR(20) NOT NULL, PRIMARY KEY(role_name,object_name,privilege_name));
CREATE TABLE access_requests (request_id INT PRIMARY KEY, actor VARCHAR(20) NOT NULL, object_name VARCHAR(20) NOT NULL, privilege_name VARCHAR(20) NOT NULL);
